<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { onBeforeRouteLeave, onBeforeRouteUpdate } from 'vue-router'
import { locale, t } from '../i18n'
import { departmentPath, orderedDepartments as orderDepartments, permits, type Department, type OrganizationContext, type OrganizationMember } from '../organization'
import { useSettingsScope } from './settingsScope'
import { useLayoutBoolean } from '../layoutScope'
import OrganizationModal from './OrganizationModal.vue'
import SidebarCollapseButton from './SidebarCollapseButton.vue'
import { Button } from './ui/button'
type Group={id:string;name:string;description:string;permissions:string[];memberIds:string[];memberCount:number}
type Permission={key:string;name:string;description?:string;group?:string;delegable?:boolean}
const props=defineProps<{context:OrganizationContext;section:string}>(),emit=defineEmits<{(event:'changed'):void}>(),scope=useSettingsScope()
const departments=ref<Department[]>([]),groups=ref<Group[]>([]),members=ref<OrganizationMember[]>([]),permissions=ref<Permission[]>([]),selected=ref(''),query=ref(''),memberSearch=ref('')
const directorySidebarExpanded=useLayoutBoolean('organization.directory.sidebar',true)
const loading=ref(false),saving=ref(false),opened=ref(false),editing=ref<Department|Group|null>(null),error=ref(''),notice=ref(''),baseline=ref('')
const form=reactive({name:'',code:'',parentId:'',status:'active',sortOrder:0,description:'',permissions:[] as string[],memberIds:[] as string[]})
const isDepartments=computed(()=>props.section==='departments'),canManage=computed(()=>!scope.locked.value&&(isDepartments.value?permits(props.context,'departments.manage'):props.context.isTenantAdmin))
const selectedDepartment=computed(()=>departments.value.find(item=>item.id===selected.value))
const selectedGroup=computed(()=>groups.value.find(item=>item.id===selected.value))
const shownMembers=computed(()=>members.value.filter(item=>isDepartments.value?item.departmentIds.includes(selected.value):selected.value==='system-admin'?item.tenantRole==='tenant_admin':selected.value==='system-members'?item.tenantRole!=='tenant_admin':selectedGroup.value?.memberIds.includes(item.id)))
const orderedDepartments=computed(()=>orderDepartments(departments.value,locale.value))
const filteredDepartments=computed(()=>orderedDepartments.value.filter(item=>!query.value.trim()||departmentPath(item,departments.value).includes(query.value.trim())||item.code.toLowerCase().includes(query.value.trim().toLowerCase())))
const eligibleParents=computed(()=>orderedDepartments.value.filter(item=>item.id!==editing.value?.id&&!hasAncestor(item,editing.value?.id||'')))
const groupCandidates=computed(()=>members.value.filter(item=>!memberSearch.value.trim()||[item.name,item.email].join(' ').toLowerCase().includes(memberSearch.value.trim().toLowerCase())))
const dirty=computed(()=>opened.value&&JSON.stringify(form)!==baseline.value)
let projectLeaveApproved=false
const message=(cause:unknown)=>cause instanceof Error?cause.message:'操作失败，请稍后重试'
function hasAncestor(item:Department,id:string){let parent=item.parentId;const seen=new Set<string>();while(parent&&!seen.has(parent)){if(parent===id)return true;seen.add(parent);parent=departments.value.find(item=>item.id===parent)?.parentId||null}return false}
async function load(){loading.value=true;error.value='';try{const [directory,people]=await Promise.all([scope.request<{items:Department[]}>('/organization/departments'),scope.request<{items:OrganizationMember[]}>('/organization/members')]);departments.value=directory.items;members.value=people.items;if(!isDepartments.value&&props.context.isTenantAdmin){const [data,catalog]=await Promise.all([scope.request<{items:Group[]}>('/organization/groups'),scope.request<{items:Permission[]}>('/organization/permissions')]);groups.value=data.items;permissions.value=catalog.items}if(!selected.value||isDepartments.value&&!departments.value.some(item=>item.id===selected.value))selected.value=isDepartments.value?departments.value[0]?.id||'':'system-admin'}catch(cause){error.value=message(cause)}finally{loading.value=false}}
function open(item?:Department|Group){if(!canManage.value||saving.value)return;editing.value=item||null;const dep=item as Department|undefined,group=item as Group|undefined;Object.assign(form,{name:item?.name||'',code:dep?.code||'',parentId:dep?.parentId||'',status:dep?.status||'active',sortOrder:dep?.sortOrder||0,description:group?.description||'',permissions:[...(group?.permissions||[])],memberIds:[...(group?.memberIds||[])]});memberSearch.value='';baseline.value=JSON.stringify(form);error.value='';opened.value=true}
function close(){if(saving.value)return;if(dirty.value&&!window.confirm(t('放弃尚未保存的设置修改？')))return;opened.value=false}
async function save(){if(saving.value||!canManage.value)return;saving.value=true;error.value='';try{const path='/organization/'+(isDepartments.value?'departments':'groups')+(editing.value?'/'+editing.value.id:'');const body=isDepartments.value?{name:form.name,code:form.code,parentId:form.parentId||null,sortOrder:form.sortOrder,...(editing.value?{status:form.status}:{})}:{name:form.name,description:form.description,permissions:form.permissions,memberIds:form.memberIds};const result=await scope.request<{id:string}>(path,{method:editing.value?'PATCH':'POST',body:JSON.stringify(body)});opened.value=false;selected.value=result.id;notice.value=isDepartments.value?'部门配置已保存':'用户组权限已保存';await load();emit('changed')}catch(cause){error.value=message(cause)}finally{saving.value=false}}
async function remove(item:Department|Group){if(saving.value||!canManage.value||!window.confirm(t('确定删除「{name}」？',{name:item.name})))return;saving.value=true;error.value='';try{await scope.request('/organization/'+(isDepartments.value?'departments':'groups')+'/'+item.id,{method:'DELETE'});selected.value='';await load();emit('changed');notice.value='配置已删除'}catch(cause){error.value=message(cause)}finally{saving.value=false}}
function selectAll(checked:boolean){form.permissions=checked?permissions.value.filter(item=>item.delegable!==false).map(item=>item.key):[]}
function canLeave(){return !saving.value&&(projectLeaveApproved||!dirty.value||window.confirm(t('放弃尚未保存的设置修改？')))}
function beforeProjectChange(event:Event){projectLeaveApproved=false;if(!canLeave())event.preventDefault();else projectLeaveApproved=true}
function cancelProjectLeave(){projectLeaveApproved=false}
function beforeUnload(event:BeforeUnloadEvent){const switching=projectLeaveApproved&&(localStorage.getItem('devflow-project')||'prj_orbit')!==scope.project;if(!switching&&(dirty.value||saving.value)){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(canLeave);onBeforeRouteUpdate(canLeave)
onMounted(()=>{void load();window.addEventListener('beforeunload',beforeUnload);window.addEventListener('devflow-before-project-change',beforeProjectChange);window.addEventListener('devflow-project-change-cancelled',cancelProjectLeave)})
onBeforeUnmount(()=>{window.removeEventListener('beforeunload',beforeUnload);window.removeEventListener('devflow-before-project-change',beforeProjectChange);window.removeEventListener('devflow-project-change-cancelled',cancelProjectLeave)})
</script>
<template>
  <section v-if="isDepartments||context.isTenantAdmin" :aria-busy="loading||saving"><p class="org-note">{{t(isDepartments?'部门关系以组织架构为准，人员选择器自动按部门成员过滤。':'权限组仅授予企业管理能力。项目角色和工作流流转权限独立配置。')}}</p><p v-if="error&&!opened" class="org-error" role="alert">{{t(error)}}</p><p v-if="notice" class="org-success" role="status">{{t(notice)}}</p><div class="org-directory" :class="{'list-collapsed':!directorySidebarExpanded}"><aside class="org-directory-list" :class="{'is-collapsed':!directorySidebarExpanded}"><SidebarCollapseButton :expanded="directorySidebarExpanded" :label="t('组织目录侧边栏')" @toggle="directorySidebarExpanded=!directorySidebarExpanded"/><div v-show="directorySidebarExpanded" class="org-directory-list-content"><header><b>{{t(isDepartments?'组织架构':'用户组')}}</b><Button v-if="canManage" size="sm" variant="outline" @click="open()">＋ {{t('新建')}}</Button></header><input v-if="isDepartments" v-model="query" :aria-label="t('查找部门')" :placeholder="t('查找部门')"><p v-if="loading" class="org-note">{{t('正在加载…')}}</p><nav :aria-label="t(isDepartments?'组织架构':'用户组')"><template v-if="isDepartments"><button v-for="item in filteredDepartments" :key="item.id" :class="{active:selected===item.id}" @click="selected=item.id" @dblclick="open(item)"><span>{{departmentPath(item,departments)}}<small>{{item.code}}<i v-if="item.status!=='active'"> · {{t('已停用')}}</i></small></span><em>{{item.memberCount}}</em></button></template><template v-else><button :class="{active:selected==='system-admin'}" @click="selected='system-admin'"><span>{{t('企业管理员')}}<small>{{t('系统安全角色')}}</small></span><em>{{members.filter(item=>item.tenantRole==='tenant_admin').length}}</em></button><button :class="{active:selected==='system-members'}" @click="selected='system-members'"><span>{{t('普通成员')}}<small>{{t('系统安全角色')}}</small></span><em>{{members.filter(item=>item.tenantRole!=='tenant_admin').length}}</em></button><button v-for="group in groups" :key="group.id" :class="{active:selected===group.id}" @click="selected=group.id" @dblclick="open(group)"><span>{{group.name}}<small>{{t('自定义权限组')}}</small></span><em>{{group.memberCount}}</em></button></template></nav></div></aside>
      <section class="org-directory-detail"><header><div><h2>{{isDepartments?selectedDepartment?.name:selectedGroup?.name||t(selected==='system-admin'?'企业管理员':'普通成员')}}</h2><p class="org-note">{{isDepartments?selectedDepartment?.code:selectedGroup?.description||t(selected==='system-admin'?'管理员拥有企业治理权限，系统安全角色不可通过权限组降级。':'普通成员默认不拥有企业治理权限，可额外加入权限组。')}}</p></div><div v-if="canManage&&(selectedDepartment&&isDepartments||selectedGroup&&!isDepartments)" class="org-actions"><Button size="sm" variant="outline" @click="open(isDepartments?selectedDepartment:selectedGroup)">{{t('编辑')}}</Button><Button size="sm" variant="ghost" :disabled="saving||isDepartments&&((selectedDepartment?.memberCount||0)>0||departments.some(item=>item.parentId===selected))" @click="remove((isDepartments?selectedDepartment:selectedGroup)!)">{{t('删除')}}</Button></div></header><p v-if="isDepartments" class="org-note">{{t('双击左侧部门可快速编辑；有成员或子部门时不能删除。')}}</p><div v-if="!isDepartments" class="org-permission-preview"><h3>{{t('企业管理权限')}}</h3><p v-if="selected==='system-members'" class="org-note">{{t('本系统角色不附加管理权限。成员可能从自定义权限组获得额外授权。')}}</p><label v-for="permission in selected==='system-admin'?permissions:permissions.filter(item=>selectedGroup?.permissions.includes(item.key))" :key="permission.key"><span>✓</span><b>{{t(permission.name)}}</b><small>{{permission.key}}</small></label><p v-if="selectedGroup&&!selectedGroup.permissions.length" class="org-note">{{t('此用户组尚未配置权限')}}</p></div><div class="org-tools"><h3>{{t('部门成员')}} <small>{{shownMembers.length}}</small></h3><RouterLink v-if="isDepartments" class="org-note" to="/organization/members">{{t('前往成员编辑')}} ↗</RouterLink></div><div class="org-table-wrap"><table class="org-table"><thead><tr><th>{{t('姓名')}}</th><th>{{t('邮箱')}}</th><th>{{t('状态')}}</th></tr></thead><tbody><tr v-for="member in shownMembers" :key="member.id"><td>{{member.name}}</td><td>{{member.email}}</td><td>{{t(member.active?'已启用':'未激活 / 已停用')}}</td></tr><tr v-if="!shownMembers.length"><td colspan="3" class="org-empty">{{t('暂无成员')}}</td></tr></tbody></table></div></section></div>
    <OrganizationModal v-if="opened" :title="t(isDepartments?(editing?'编辑部门':'新建部门'):(editing?'编辑用户组':'新建用户组'))" :busy="saving" wide @close="close"><form id="org-directory-form" class="org-form" :inert="saving" @submit.prevent="save"><label>{{t('名称')}} *<input v-model="form.name" required maxlength="80"></label><template v-if="isDepartments"><div class="org-form-two"><label>{{t('部门代码')}}<input v-model="form.code" maxlength="64" :placeholder="t('用于 CSV 导入匹配')"></label><label>{{t('排序')}}<input v-model.number="form.sortOrder" type="number" min="0" max="999999"></label></div><label>{{t('上级部门')}}<select v-model="form.parentId"><option value="">{{t('无上级部门')}}</option><option v-for="item in eligibleParents" :key="item.id" :value="item.id">{{departmentPath(item,departments)}}</option></select></label><label v-if="editing">{{t('部门状态')}}<select v-model="form.status"><option value="active">{{t('已启用')}}</option><option value="inactive">{{t('已停用')}}</option></select></label></template><template v-else><label>{{t('说明')}}<textarea v-model="form.description" maxlength="1000"></textarea></label><fieldset><legend>{{t('企业管理权限')}}</legend><div class="org-actions"><Button type="button" variant="ghost" size="sm" @click="selectAll(true)">{{t('全选')}}</Button><Button type="button" variant="ghost" size="sm" @click="selectAll(false)">{{t('清空')}}</Button></div><div class="org-permission-grid"><label v-for="permission in permissions.filter(item=>item.delegable!==false)" :key="permission.key" class="org-check"><input v-model="form.permissions" type="checkbox" :value="permission.key"><span>{{t(permission.name)}}<small>{{t(permission.description||permission.key)}}</small></span></label></div></fieldset><fieldset><legend>{{t('用户组成员')}}</legend><input v-model="memberSearch" :placeholder="t('搜索姓名或邮箱')" :aria-label="t('搜索姓名或邮箱')"><div class="org-multi"><label v-for="member in groupCandidates" :key="member.id" class="org-check"><input v-model="form.memberIds" type="checkbox" :value="member.id">{{member.name}} · {{member.email}}</label></div></fieldset><p class="org-note">{{t('用户组权限变更会立即生效，并记录企业审计日志。')}}</p></template><p v-if="error" class="org-error" role="alert">{{t(error)}}</p></form><template #footer><Button variant="outline" :disabled="saving" @click="close">{{t('取消')}}</Button><Button form="org-directory-form" type="submit" :disabled="saving||!canManage">{{t('保存配置')}}</Button></template></OrganizationModal>
  </section><p v-else class="org-error" role="alert">{{t('只有企业管理员可以管理用户组权限')}}</p>
</template>
<style scoped>
.org-directory{display:grid;grid-template-columns:240px minmax(0,1fr);border:1px solid var(--line);border-radius:12px;overflow:hidden;min-height:480px;transition:grid-template-columns .16s ease}.org-directory.list-collapsed{grid-template-columns:52px minmax(0,1fr)}.org-directory-list{padding:16px;border-right:1px solid var(--line);background:var(--surface-soft,#f8fafc);display:flex;flex-direction:column;transition:padding .16s ease}.org-directory-list>.sidebar-collapse-toggle{align-self:flex-end;margin:-7px -5px 10px}.org-directory-list.is-collapsed{padding:12px}.org-directory-list.is-collapsed>.sidebar-collapse-toggle{align-self:center;margin:0}.org-directory-list-content{display:flex;flex-direction:column;gap:12px;min-width:0;width:100%}.org-directory-list-content>input{display:block;box-sizing:border-box;min-width:0;width:100%;max-width:100%;flex:none;padding:9px 10px;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--ink)}.org-directory-list-content>header{flex-wrap:wrap;gap:8px;margin-bottom:0}.org-directory-list-content nav{min-width:0}.org-directory-list-content nav button>span{min-width:0;overflow-wrap:anywhere}.org-directory-list-content nav button>em{flex:none}.org-directory-list header{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;font-size:13px}.org-directory-list>input{width:100%;margin-bottom:12px}.org-directory-list nav{display:grid;gap:7px}.org-directory-list nav button{display:flex;gap:8px;align-items:center;justify-content:space-between;border:1px solid transparent;background:transparent;border-radius:8px;padding:12px 10px;text-align:left;color:inherit;font-size:12px}.org-directory-list nav button.active{background:var(--surface,#fff);border-color:color-mix(in srgb,var(--primary) 30%,transparent);color:var(--primary);box-shadow:0 4px 12px #1e293b06}.org-directory-list small{font-size:10px;display:block;color:var(--muted);margin-top:5px}.org-directory-list i,.org-directory-list em{font-style:normal}.org-directory-list em{background:var(--primary-soft);padding:2px 6px;border-radius:5px;font-size:10px}.org-directory-detail{padding:22px;min-width:0}.org-directory-detail>header{display:flex;justify-content:space-between;gap:15px;align-items:flex-start;margin-bottom:14px}.org-directory-detail h2{font-size:18px;margin:0}.org-directory-detail h3{font-size:13px}.org-directory-detail h3 small{font-size:11px;color:var(--muted);font-weight:400}.org-permission-preview{display:flex;gap:10px;flex-wrap:wrap;border:1px solid var(--line);border-radius:10px;padding:15px;margin:20px 0}.org-permission-preview h3{width:100%;margin:0 0 8px}.org-permission-preview>label{display:grid;grid-template-columns:16px 1fr;align-items:center;gap:4px;font-size:12px;min-width:170px;padding:7px}.org-permission-preview>label>span{color:#10b981}.org-permission-preview>label>b{font-weight:500}.org-permission-preview>label>small{grid-column:2;font-size:9px;color:var(--muted)}.org-permission-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}.org-permission-grid small{display:block}.org-directory-detail .org-note{overflow-wrap:anywhere}@media(max-width:1100px){.org-directory{grid-template-columns:205px minmax(0,1fr)}.org-directory.list-collapsed{grid-template-columns:52px minmax(0,1fr)}.org-directory-detail{padding:16px}}
</style>
